return ['domain'=>'pnscripts-product-tabs','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'PN Product Tabs 1.0.1','pot-creation-date'=>'2026-10-05T12:35:24+00:00','po-revision-date'=>'2026-10-04 00:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PN Product Tabs – Custom Tabs & FAQ'=>'PN Product Tabs – Custom Tabs & FAQ','https://pnscripts.com/marketplace/pn-product-tabs'=>'https://pnscripts.com/marketplace/pn-product-tabs','Custom product tabs per product, reusable global tabs by category or tag, FAQ tabs with optional FAQPage schema, rename, reorder or hide the default tabs, and a one-click importer from YIKES Custom Product Tabs. Works in classic and block themes.'=>'Własne zakładki dla każdego produktu, globalne zakładki według kategorii lub tagów, zakładki FAQ z opcjonalnym schematem FAQPage, zmiana nazwy, kolejności lub ukrywanie domyślnych zakładek oraz import jednym kliknięciem z YIKES Custom Product Tabs. Działa z motywami klasycznymi i blokowymi.','PN Scripts'=>'PN Scripts','https://pnscripts.com'=>'https://pnscripts.com','Tab settings'=>'Ustawienia zakładek','Tab type'=>'Typ zakładki','Rich text: the content written in the editor above'=>'Tekst: treść wpisana w edytorze powyżej','FAQ: questions and answers below'=>'FAQ: pytania i odpowiedzi poniżej','Add question'=>'Dodaj pytanie','Publish as FAQPage structured data'=>'Publikuj jako dane strukturalne FAQPage','Show this tab on'=>'Pokazuj tę zakładkę na','All products'=>'Wszystkich produktach','Products in these categories or with these tags'=>'Produktach z tych kategorii lub z tymi tagami','Only products where I add it (Product data → Custom tabs)'=>'Tylko produktach, do których go dodam (Dane produktu → Własne zakładki)','Categories (subcategories included)'=>'Kategorie (łącznie z podkategoriami)','Choose categories…'=>'Wybierz kategorie…','Tags'=>'Tagi','Choose tags…'=>'Wybierz tagi…','Position (priority)'=>'Pozycja (priorytet)','Lower numbers come first. WooCommerce uses 10 for Description, 20 for Additional information and 30 for Reviews (change these under Products → Tab settings).'=>'Niższe liczby są pierwsze. WooCommerce używa 10 dla Opisu, 20 dla Informacji dodatkowych i 30 dla Opinii (zmienisz to w Produkty → Ustawienia zakładek).','Question'=>'Pytanie','Answer'=>'Odpowiedź','Remove question'=>'Usuń pytanie','Shown on'=>'Wyświetlana na','Type'=>'Typ','Priority'=>'Priorytet','FAQ'=>'FAQ','Rich text'=>'Tekst','Products where added'=>'Produkty, do których ją dodano','No categories or tags chosen'=>'Nie wybrano kategorii ani tagów','Custom tabs'=>'Własne zakładki','Remove this tab? It is deleted when you update the product.'=>'Usunąć tę zakładkę? Zostanie usunięta po zaktualizowaniu produktu.','(no title)'=>'(bez tytułu)','Tabs shown on this product, in this order (drag to reorder). Rich-text tabs accept anything the editor does; FAQ tabs show questions as an accessible list and can publish FAQPage structured data.'=>'Zakładki tego produktu w tej kolejności (przeciągnij, aby zmienić). Zakładki tekstowe przyjmują wszystko, co obsługuje edytor; zakładki FAQ pokazują pytania jako dostępną listę i mogą publikować dane strukturalne FAQPage.','No custom tabs on this product yet.'=>'Ten produkt nie ma jeszcze własnych zakładek.','Add tab'=>'Dodaj zakładkę','Add FAQ tab'=>'Dodaj zakładkę FAQ','Global tab to add'=>'Globalna zakładka do dodania','Add a global tab…'=>'Dodaj globalną zakładkę…','Add'=>'Dodaj','Manage global tabs'=>'Zarządzaj globalnymi zakładkami','Global tabs shown automatically'=>'Globalne zakładki wyświetlane automatycznie','Hide "%s" on this product'=>'Ukryj „%s” na tym produkcie','WooCommerce tabs on this product'=>'Zakładki WooCommerce w tym produkcie','(deleted global tab)'=>'(usunięta zakładka globalna)','Global'=>'Globalna','Drag to reorder'=>'Przeciągnij, aby zmienić kolejność','Imported'=>'Zaimportowana','Show'=>'Pokazuj','Remove'=>'Usuń','Content comes from the global tab and updates everywhere when you edit it.'=>'Treść pochodzi z globalnej zakładki i aktualizuje się wszędzie, gdy ją edytujesz.','Edit global tab'=>'Edytuj globalną zakładkę','Tab title'=>'Tytuł zakładki','Tab content'=>'Treść zakładki','Description'=>'Opis','Additional information'=>'Informacje dodatkowe','Reviews'=>'Opinie','Product tab settings'=>'Ustawienia zakładek produktu','Settings'=>'Ustawienia','Global tabs'=>'Globalne zakładki','Import the YIKES tabs now? YIKES data is not changed and you can undo the import.'=>'Zaimportować teraz zakładki YIKES? Dane YIKES nie są zmieniane, a import można cofnąć.','Remove all tabs created by the import (tabs you added yourself stay)?'=>'Usunąć wszystkie zakładki utworzone przez import (dodane przez Ciebie zostaną)?','Working… %d products handled'=>'Trwa praca… przetworzono produktów: %d','The request failed. Reload the page and try again.'=>'Żądanie nie powiodło się. Odśwież stronę i spróbuj ponownie.','Dry run finished: nothing was changed. These numbers are what an import will do.'=>'Próba zakończona: nic nie zostało zmienione. Te liczby pokazują, co zrobi import.','Import finished. Check a few product pages, then deactivate YIKES Custom Product Tabs.'=>'Import zakończony. Sprawdź kilka stron produktów, a potem dezaktywuj YIKES Custom Product Tabs.','Import removed.'=>'Import usunięty.','… and %d more notes like these.'=>'… i jeszcze %d podobnych uwag.','Products with YIKES tabs'=>'Produkty z zakładkami YIKES','YIKES saved tabs'=>'Zapisane zakładki YIKES','Global tabs to create / created'=>'Globalne zakładki do utworzenia / utworzone','Saved tabs imported before (left as they are)'=>'Zapisane zakładki zaimportowane wcześniej (bez zmian)','Products to import / imported'=>'Produkty do importu / zaimportowane','Products unchanged since the last import (skipped)'=>'Produkty bez zmian od ostatniego importu (pominięte)','Product tabs copied'=>'Skopiowane zakładki produktów','Product tabs linked to a global tab'=>'Zakładki produktów powiązane z globalną zakładką','Tabs without a title (imported switched off)'=>'Zakładki bez tytułu (zaimportowane jako wyłączone)','Tabs hidden by a duplicate title in YIKES (imported switched off)'=>'Zakładki ukryte przez powtórzony tytuł w YIKES (zaimportowane jako wyłączone)','Default tabs YIKES replaced (hidden on those products)'=>'Domyślne zakładki zastąpione przez YIKES (ukryte w tych produktach)','Imported global tabs removed'=>'Usunięte zaimportowane zakładki globalne','Products cleaned'=>'Wyczyszczone produkty','You are not allowed to import tabs.'=>'Nie masz uprawnień do importu zakładek.','Import from YIKES'=>'Import z YIKES','WooCommerce tabs'=>'Zakładki WooCommerce','Rename, reorder or hide the standard tabs on every product (single products can hide them too, under Product data → Custom tabs). Leave a title empty to keep WooCommerce\'s title; in the Reviews title, %s becomes the number of reviews.'=>'Zmień nazwę, kolejność lub ukryj standardowe zakładki we wszystkich produktach (pojedyncze produkty też mogą je ukryć w Dane produktu → Własne zakładki). Zostaw pusty tytuł, aby zachować tytuł WooCommerce; w tytule Opinii %s zamienia się w liczbę opinii.','Tab'=>'Zakładka','Title'=>'Tytuł','Priority of product tabs'=>'Priorytet zakładek produktu','The first tab added on a product gets this priority, the next one +1, and so on. 25 places them between Additional information and Reviews. Global tabs have their own priority.'=>'Pierwsza zakładka produktu otrzymuje ten priorytet, następna +1 itd. 25 umieszcza je między Informacjami dodatkowymi a Opiniami. Zakładki globalne mają własny priorytet.','Display'=>'Wyświetlanie','Keep Reviews as the last tab'=>'Opinie zawsze jako ostatnia zakładka','Repeat the tab title as a heading inside the tab (classic tabs; never inside accordions)'=>'Powtarzaj tytuł jako nagłówek w zakładce (klasyczne zakładki; nigdy w akordeonach)','Output FAQPage structured data for FAQ tabs that allow it (turn off if your SEO plugin already adds FAQ markup)'=>'Wyświetlaj dane strukturalne FAQPage dla zakładek FAQ, które na to pozwalają (wyłącz, jeśli wtyczka SEO już dodaje znaczniki FAQ)','While YIKES Custom Product Tabs is still active, hide its copy of tabs that were imported'=>'Dopóki YIKES Custom Product Tabs jest aktywny, ukrywaj jego kopie zaimportowanych zakładek','Uninstall'=>'Odinstalowanie','Delete all tabs and settings of this plugin when it is deleted from the Plugins screen'=>'Usuń wszystkie zakładki i ustawienia tej wtyczki, gdy zostanie usunięta z ekranu Wtyczki','Off by default, so deleting and reinstalling the plugin keeps your tabs. YIKES data is never touched.'=>'Domyślnie wyłączone, więc usunięcie i ponowna instalacja zachowa zakładki. Dane YIKES nigdy nie są zmieniane.','Copies the tabs of "Custom Product Tabs for WooCommerce" by YIKES: every product\'s tabs (in the same order, with the same content) and the saved tabs, which become global tabs. Products that used a saved tab are linked to the new global tab, so editing it updates them all. Saved tabs that the YIKES Pro add-on assigned to all products or to categories/tags keep those rules.'=>'Kopiuje zakładki „Custom Product Tabs for WooCommerce” od YIKES: zakładki każdego produktu (w tej samej kolejności, z tą samą treścią) oraz zapisane zakładki, które stają się globalne. Produkty, które używały zapisanej zakładki, zostają z nią powiązane, więc jej edycja aktualizuje wszystkie. Zapisane zakładki, które dodatek YIKES Pro przypisał do wszystkich produktów lub do kategorii/tagów, zachowują te reguły.','YIKES data is only read. Nothing is changed or deleted, and YIKES keeps working until you deactivate it.'=>'Dane YIKES są tylko odczytywane. Nic nie jest zmieniane ani usuwane, a YIKES działa, dopóki go nie dezaktywujesz.','Running it again is safe: tabs are never duplicated, and products whose YIKES tabs did not change are skipped.'=>'Ponowne uruchomienie jest bezpieczne: zakładki nigdy się nie dublują, a produkty bez zmian w YIKES są pomijane.','Tabs YIKES never showed (no title, or hidden by another tab with the same title) are imported switched off and listed below.'=>'Zakładki, których YIKES nigdy nie pokazywał (bez tytułu lub ukryte przez inną zakładkę o tym samym tytule), są importowane jako wyłączone i wymienione poniżej.','Large catalogues are handled in batches of 100 products. Command line: wp pnscripts-product-tabs import-yikes --dry-run'=>'Duże katalogi są przetwarzane partiami po 100 produktów. Wiersz poleceń: wp pnscripts-product-tabs import-yikes --dry-run','Found:'=>'Znaleziono:','%d product with YIKES tabs'=>'%d produkt z zakładkami YIKES' . "\0" . '%d produkty z zakładkami YIKES' . "\0" . '%d produktów z zakładkami YIKES','YIKES plugin active'=>'wtyczka YIKES aktywna','YIKES plugin not active (data can still be imported)'=>'wtyczka YIKES nieaktywna (dane nadal można zaimportować)','last import: %s'=>'ostatni import: %s','Dry run (change nothing)'=>'Próba (bez zmian)','Import now'=>'Importuj teraz','Undo import'=>'Cofnij import','Notes'=>'Uwagi','PN Product Tabs found tabs from Custom Product Tabs for WooCommerce (YIKES). Import them in one click; YIKES data stays untouched.'=>'PN Product Tabs znalazł zakładki z Custom Product Tabs for WooCommerce (YIKES). Zaimportuj je jednym kliknięciem; dane YIKES pozostaną nietknięte.','Review the import'=>'Sprawdź import','Dismiss'=>'Odrzuć','Saved tab #%d has no title and was skipped.'=>'Zapisana zakładka #%d nie ma tytułu i została pominięta.','Saved tab "%1$s" was assigned by the taxonomy "%2$s", which is not supported; it is imported for the categories and tags only.'=>'Zapisana zakładka „%1$s” była przypisana według taksonomii „%2$s”, która nie jest obsługiwana; importowana jest tylko dla kategorii i tagów.','Product #%d: a tab without a title (never shown by YIKES) was imported switched off.'=>'Produkt #%d: zakładka bez tytułu (nigdy niepokazywana przez YIKES) została zaimportowana jako wyłączona.','Product #%1$d: the tab "%2$s" was hidden by a later tab with the same title in YIKES; it was imported switched off.'=>'Produkt #%1$d: zakładka „%2$s” była ukryta przez późniejszą zakładkę o tym samym tytule w YIKES; zaimportowano ją jako wyłączoną.','PN Product Tabs needs WooCommerce %s or newer to be active.'=>'PN Product Tabs wymaga aktywnego WooCommerce w wersji %s lub nowszej.','Global product tabs'=>'Globalne zakładki produktów','Global product tab'=>'Globalna zakładka produktu','Product tabs'=>'Zakładki produktów','Add global tab'=>'Dodaj globalną zakładkę','New global tab'=>'Nowa globalna zakładka','Search global tabs'=>'Szukaj globalnych zakładek','No global tabs yet.'=>'Brak globalnych zakładek.','No global tabs in the trash.'=>'Brak globalnych zakładek w koszu.','Global tab updated.'=>'Globalna zakładka zaktualizowana.','Global tab published.'=>'Globalna zakładka opublikowana.','Reusable tabs shown on all products, on products in chosen categories or tags, or where added manually.'=>'Zakładki wielokrotnego użytku wyświetlane na wszystkich produktach, w wybranych kategoriach lub tagach albo tam, gdzie dodano je ręcznie.','Sorry, you are not allowed to view global product tabs.'=>'Nie masz uprawnień do przeglądania globalnych zakładek produktów.']];